const Redis = require('/files/node_modules/ioredis');
const fs = require('fs');
const cfg = JSON.parse(fs.readFileSync('/files/redis.json', 'utf8'));

const r = new Redis({
  host: cfg.host || 'botredis',
  port: cfg.port || 6379,
  password: cfg.password,
  connectTimeout: 4000,
  maxRetriesPerRequest: 2
});
r.on('error', () => {});

function dayKey(offsetDays = 0) {
  const d = new Date(Date.now() + offsetDays * 86400000);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
}
function monthKey(offsetDays = 0) {
  const d = new Date(Date.now() + offsetDays * 86400000);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`;
}

// ─────────────────────────────────────────────────────────
// Phone numbers (WhatsApp Business) — for per-number billing
// ─────────────────────────────────────────────────────────
const PHONE_NUMBERS = [
  { inboxId: 10, phoneNumberId: '1111231948738550', label: '01000000000' },
  { inboxId: 11, phoneNumberId: '1015579888315502', label: '01000000000' },
  { inboxId: 12, phoneNumberId: '963488543523802',  label: '01000000000' },
  { inboxId: 16, phoneNumberId: '1123949100810776', label: 'VIP (01000000000)' },
  { inboxId: 19, phoneNumberId: '1243217355535246', label: 'صالة (01000000000)' }
];

const META_SERVICE_RATE_USD = 0.0036;
const META_FREE_PER_NUMBER_MONTHLY = 1000;

// ─────────────────────────────────────────────────────────
// Read token totals for a day
// ─────────────────────────────────────────────────────────
async function sumTokensForDay(day) {
  const keys = new Set();
  let cursor = '0';
  do {
    const [nc, batch] = await r.scan(cursor, 'MATCH', `tokens:daily:${day}:*`, 'COUNT', 200);
    cursor = nc;
    batch.forEach(k => keys.add(k));
  } while (cursor !== '0');

  const byMode = {};
  const byModel = {};
  let grandPrompt = 0, grandCompletion = 0, grandRequests = 0, grandCostMicro = 0;

  for (const k of keys) {
    const val = Number(await r.get(k)) || 0;
    const parts = k.split(':');
    const provider = parts[3];
    const mode = parts[4];

    // Model-level keys: parts[5]="model", parts[6]=<modelName>, parts[7]=<field>
    if (parts[5] === 'model' && parts.length >= 8) {
      const model = parts[6];
      const field = parts[7];
      const bucket = `${provider}:${mode}:${model}`;
      if (!byModel[bucket]) byModel[bucket] = { prompt: 0, completion: 0, requests: 0, costMicro: 0, audioSeconds: 0 };
      if (field === 'prompt') byModel[bucket].prompt += val;
      else if (field === 'completion') byModel[bucket].completion += val;
      else if (field === 'requests') byModel[bucket].requests += val;
      else if (field === 'costMicro') byModel[bucket].costMicro += val;
      else if (field === 'audioSeconds') byModel[bucket].audioSeconds += val;
      continue;
    }

    const suffix = parts.slice(5).join(':');
    const bucket = `${provider}:${mode}`;
    if (!byMode[bucket]) byMode[bucket] = { prompt: 0, completion: 0, requests: 0, costMicro: 0, audioSeconds: 0 };
    if (suffix === 'prompt') { byMode[bucket].prompt += val; grandPrompt += val; }
    else if (suffix === 'completion') { byMode[bucket].completion += val; grandCompletion += val; }
    else if (suffix === 'requests') { byMode[bucket].requests += val; grandRequests += val; }
    else if (suffix === 'costMicro') { byMode[bucket].costMicro += val; grandCostMicro += val; }
    else if (suffix === 'audioSeconds') byMode[bucket].audioSeconds += val;
  }

  return {
    byMode, byModel,
    grandPrompt, grandCompletion, grandRequests, grandCostMicro,
    grandTotal: grandPrompt + grandCompletion,
    grandCostUSD: grandCostMicro / 1_000_000
  };
}

// ─────────────────────────────────────────────────────────
// Meta usage — per phone number
// ─────────────────────────────────────────────────────────
async function readMetaUsage(day, month) {
  const dailySent      = Number(await r.get(`msgcount:daily:${day}:sent`)) || 0;
  const monthlyService = Number(await r.get(`msgcount:monthly:${month}:service`)) || 0;

  const perNumber = [];
  let totalBillable = 0;
  let totalCostUSD = 0;

  for (const { inboxId, phoneNumberId, label } of PHONE_NUMBERS) {
    const monthCount = Number(await r.get(`msgcount:monthly:${month}:phone:${phoneNumberId}:service`)) || 0;
    const dailyCount = Number(await r.get(`msgcount:daily:${day}:phone:${phoneNumberId}:sent`)) || 0;

    const billable = Math.max(0, monthCount - META_FREE_PER_NUMBER_MONTHLY);
    const cost = billable * META_SERVICE_RATE_USD;

    perNumber.push({
      inboxId, phoneNumberId, label,
      monthCount, dailyCount,
      billable,
      costUSD: cost
    });

    totalBillable += billable;
    totalCostUSD += cost;
  }

  return {
    dailySent,
    monthlyService,
    perNumber,
    totalBillable,
    totalCostUSD
  };
}

// ─────────────────────────────────────────────────────────
// Main
// ─────────────────────────────────────────────────────────
const today = dayKey(0);
const yesterday = dayKey(-1);
const thisMonth = monthKey(0);

const t = await sumTokensForDay(today);
const y = await sumTokensForDay(yesterday);
const meta = await readMetaUsage(today, thisMonth);

// ─────────────────────────────────────────────────────────
// Build report
// ─────────────────────────────────────────────────────────
const lines = [];
lines.push(`📊 Daily Report — ${today}`);
lines.push('');

lines.push('🤖 AI Usage');
lines.push(`Input tokens:  ${t.grandPrompt.toLocaleString()}`);
lines.push(`Output tokens: ${t.grandCompletion.toLocaleString()}`);
lines.push(`AI requests:   ${t.grandRequests.toLocaleString()}`);
lines.push(`AI cost (USD): $${t.grandCostUSD.toFixed(4)}`);
lines.push('');

if (Object.keys(t.byModel).length > 0) {
  lines.push('🧠 By Model');
  for (const [bucket, data] of Object.entries(t.byModel).sort((a,b) => b[1].costMicro - a[1].costMicro)) {
    lines.push(`- ${bucket}`);
    lines.push(`  in ${data.prompt} / out ${data.completion} / req ${data.requests} / $${(data.costMicro/1_000_000).toFixed(4)}`);
    if (data.audioSeconds > 0) lines.push(`  audio ${data.audioSeconds}s`);
  }
  lines.push('');
}

lines.push('📤 WhatsApp Messages');
lines.push(`Sent today (all numbers): ${meta.dailySent}`);
lines.push(`Sent this month (all):    ${meta.monthlyService}`);
lines.push('');
lines.push('Per number (this month):');

for (const n of meta.perNumber) {
  const status = n.billable > 0 ? `billable=${n.billable} cost=$${n.costUSD.toFixed(4)}` : 'within free tier';
  lines.push(`  ${n.label}`);
  lines.push(`    sent=${n.monthCount}  ${status}`);
}

lines.push('');
lines.push(`Total billable:      ${meta.totalBillable}`);
lines.push(`Total Meta cost:     $${meta.totalCostUSD.toFixed(4)}`);
lines.push(`Free tier per number: ${META_FREE_PER_NUMBER_MONTHLY} messages`);
lines.push('');

lines.push(`Yesterday (${yesterday}):`);
lines.push(`  AI: ${y.grandTotal} tokens / ${y.grandRequests} req / $${y.grandCostUSD.toFixed(4)}`);
if (y.grandTotal > 0 && t.grandTotal > 0) {
  const diff = ((t.grandTotal - y.grandTotal) / y.grandTotal * 100).toFixed(1);
  const arrow = diff > 0 ? '📈' : diff < 0 ? '📉' : '➡️';
  lines.push(`  Token change: ${arrow} ${diff}%`);
}

lines.push('');
lines.push('ℹ️ Notes:');
lines.push('- Token cost is per-model, computed at log time.');
lines.push(`- Meta: ${META_FREE_PER_NUMBER_MONTHLY} free service messages per phone number per month.`);
lines.push(`- Rate: $${META_SERVICE_RATE_USD} per service message after the free tier.`);
lines.push('- Incoming customer messages are always free.');

await r.set(`reports:daily:${today}`, JSON.stringify({
  tokens: t, meta, generatedAt: Date.now()
}), 'EX', 7776000);

r.disconnect();

return [{
  json: { report: lines.join('\n'), raw: { tokens: t, meta, yesterday: y } }
}];
